#!/usr/bin/env bash
# Generated by: Claude Opus 5.5
# Generation date: 2026-10-10
#
# Start the bootstrap container with a locked-down setup.
#
#   --containall  own /tmp, PID and IPC namespaces; no host home, no host /tmp
#   --cleanenv    host environment variables are NOT passed in
#   --home        a dedicated sandbox home instead of your real home
#   --bind        only the work directory is visible from the host
#   --env-file    secrets come from a 600-permission file, not the command
#                 line (command-line args are visible to other users via ps)
set -euo pipefail

BASE="${LLM_BOOTSTRAP_DIR:-$HOME/projects/llm-bootstrap}"
SIF="${BASE}/bootstrap.sif"

mkdir -p "$BASE/home" "$BASE/work"
chmod 700 "$BASE" "$BASE/home"

if [[ ! -f "$SIF" ]]; then
  echo "Image not found: $SIF" >&2
  echo "Build it with: singularity build --fakeroot $SIF $BASE/bootstrap.def" >&2
  exit 1
fi

ENV_ARGS=()
if [[ -f "$BASE/secrets.env" ]]; then
  if [[ "$(stat -c %a "$BASE/secrets.env")" != "600" ]]; then
    echo "Refusing to start: run 'chmod 600 $BASE/secrets.env' first" >&2
    exit 1
  fi
  ENV_ARGS=(--env-file "$BASE/secrets.env")
fi

exec singularity run \
  --containall \
  --cleanenv \
  --home "$BASE/home:$HOME" \
  --bind "$BASE/work:/work" \
  --pwd /work \
  "${ENV_ARGS[@]}" \
  "$SIF" "$@"
